    if (end <= start) throw firstError;
    return JSON.parse(cleaned.slice(start, end + 1));
  }
}

let hyp;
try {
  hyp = parseJsonFromOutput($json.output);
} catch (e) {
  hyp = { error: 'parse failed', raw: $json.output, details: e.message };
}

return [{ json: hyp }];

// Build Report — assemble the final markdown and emit as binary for the file-writer.
const form = $('Research Form').first().json;
const topic = form['Research topic'] || form.topic || 'Unknown topic';

const agg = $('Aggregate Summaries').first().json;
const summaries = agg.summaries || [];

const comparison = $('Parse Comparison').first().json || {};
const hyp = $json || {};

const date = new Date().toISOString().slice(0, 10);

function esc(s) { return (s == null ? '' : String(s)); }
function authorLine(meta) {
  const a = (meta && meta.authors) || [];
  if (a.length === 0) return 'Unknown authors';
  if (a.length <= 4) return a.join(', ');
  return a.slice(0, 4).join(', ') + ' et al.';
}

let md = '';
md += '# Research Report: ' + topic + '\n\n';
md += '_Generated ' + date + ' by the Multi-Agent Research Assistant._\n\n';
md += '---\n\n';

md += '## 1. Literature Summary\n\n';
md += 'Reviewed **' + summaries.length + '** papers across arXiv, Semantic Scholar, and OpenAlex.\n\n';
for (const s of summaries) {
  const meta = s._meta || {};
  md += '### ' + esc(meta.title || s.title || 'Untitled') + '\n';
  md += '*' + authorLine(meta) + ' (' + esc(meta.year || 'n.d.') + ')';
  if (meta.citations != null) md += ' · ' + meta.citations + ' citations';
  md += ' · ' + esc(meta.source || '');
  if (meta.url) md += ' · [link](' + meta.url + ')';
  md += '*\n\n';
  md += '- **Problem:** ' + esc(s.problem) + '\n';
  md += '- **Method:** ' + esc(s.method) + '\n';
  md += '- **Dataset:** ' + esc(s.dataset) + '\n';
  md += '- **Architecture:** ' + esc(s.architecture) + '\n';
  md += '- **Results:** ' + esc(s.results) + '\n';
  md += '- **Limitations:** ' + esc(s.limitations) + '\n';
  md += '- **Novelty:** ' + esc(s.novelty) + '\n\n';
}

md += '## 2. Comparison\n\n';
md += (comparison.table_markdown || '_No comparison table generated._') + '\n\n';

if (comparison.clusters && comparison.clusters.length) {
  md += '### Clusters\n\n';
  for (const c of comparison.clusters) {
    md += '- **' + esc(c.name) + '** — ' + esc(c.common_thread || '') + '\n';
    md += '  - Papers: ' + (c.papers || []).join(', ') + '\n';
  }
  md += '\n';
}

if (comparison.observations) {
  md += '### Cross-paper Observations\n\n' + comparison.observations + '\n\n';
}

md += '## 3. Research Gaps\n\n';
for (const g of (hyp.research_gaps || [])) md += '- ' + esc(g) + '\n';
if (!(hyp.research_gaps && hyp.research_gaps.length)) md += '_(none identified)_\n';
md += '\n';

md += '## 4. Proposed Hypothesis\n\n';
if (hyp.hypothesis) {
  md += '> **' + esc(hyp.hypothesis.statement) + '**\n\n';
  md += esc(hyp.hypothesis.rationale) + '\n\n';
}

md += '## 5. Experiment Plan\n\n';
const ep = hyp.experiment_plan || {};
md += '**Objective:** ' + esc(ep.objective) + '\n\n';
md += '**Dataset / simulation:** ' + esc(ep.dataset_or_simulation) + '\n\n';
if ((ep.baselines || []).length) {
  md += '**Baselines:**\n';
  for (const b of ep.baselines) md += '- ' + esc(b) + '\n';
  md += '\n';
}
if ((ep.metrics || []).length) {
  md += '**Metrics:**\n';
  for (const m of ep.metrics) md += '- ' + esc(m) + '\n';
  md += '\n';
}
if ((ep.implementation_steps || []).length) {
  md += '**Implementation steps:**\n';
  ep.implementation_steps.forEach(function (step, i) { md += (i + 1) + '. ' + esc(step) + '\n'; });
  md += '\n';
}

md += '## 6. Risks & Caveats\n\n';
for (const r of (hyp.risks || [])) md += '- ' + esc(r) + '\n';
if (!(hyp.risks && hyp.risks.length)) md += '_(none identified)_\n';
md += '\n---\n\n_End of report._\n';

const safeSlug = topic.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
const filename = 'report-' + date + '-' + safeSlug + '.md';

const binary = await this.helpers.prepareBinaryData(Buffer.from(md, 'utf-8'), filename, 'text/markdown');

return [{
  json: { topic: topic, filename: filename, paper_count: summaries.length },
  binary: { data: binary },
}];

